"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[27098],{82436(e){e.exports=JSON.parse('{"tag":{"label":"chrome","permalink":"/tips/tags/chrome","allTagsPath":"/tips/tags","count":4,"items":[{"id":"chrome-driver/29-chrome-driver","title":"How to Run Your Tests Against Chrome","description":"Selenium needs a browser driver (ChromeDriver for Chrome) to drive a browser. Selenium Manager finds or downloads the driver and the browser for you, so a test only needs to ask for Chrome.","permalink":"/tips/29-chrome-driver"},{"id":"headless/38-headless","title":"How to Run Your Tests Headless with Xvfb","description":"If you want to run your tests headless on a Continuous Integration (CI) server you\'ll quickly realize that you can\'t with an out-of-the-box setup since there is no display output for the browser to launch in.","permalink":"/tips/38-headless"},{"id":"headless-chrome/72-headless-chrome","title":"How To Run Your Tests Headlessly with Chrome","description":"A Continuous Integration (CI) server usually has no display for the browser to open a window in. Chrome can run headless (without a window), so the tests run there with no extra tools.","permalink":"/tips/72-headless-chrome"},{"id":"limit-bandwidth/64-limit-bandwidth","title":"Test on a Slow Network","description":"With Selenium we can test our application on different browsers. But how does it behave on a slow connection? Chrome can limit its own network, so the tests can find out.","permalink":"/tips/64-limit-bandwidth"}],"unlisted":false}}')}}]);